"""extract_emails.py — Metnos executor v1.1
Estrae indirizzi email validi da testo libero, deduplicati e ordinati.
"""

import json
import re
import sys


# Pattern RFC-5322 semplificato: copre la stragrande maggioranza dei casi reali.
_EMAIL_RE = re.compile(
    r"""(?<![^\s<,;\"'(])          # non preceduto da caratteri "attaccati"
        ([a-zA-Z0-9._%+\-]+        # local part
         @                         # chiocciola
         [a-zA-Z0-9.\-]+           # dominio
         \.[a-zA-Z]{2,})           # TLD (almeno 2 caratteri)
        (?![^\s>,;\"')])           # non seguito da caratteri "attaccati"
    """,
    re.VERBOSE,
)


def invoke(args: dict) -> dict:
    """Estrae email valide dal campo 'text', deduplicandole e ordinandole."""
    text = args.get("text", "")

    if not isinstance(text, str):
        return {"ok": False, "error": "'text' deve essere una stringa."}

    if not text.strip():
        return {"ok": False, "error": "'text' è vuoto o contiene solo spazi."}

    raw_matches: list[str] = _EMAIL_RE.findall(text)

    # Normalizza in lowercase per deduplicazione case-insensitive,
    # ma conserva la forma originale (prima occorrenza) per l'output.
    seen: dict[str, str] = {}
    for email in raw_matches:
        key = email.lower()
        if key not in seen:
            seen[key] = email  # prima occorrenza vince

    # Ordina per chiave lowercase, restituisce la forma originale
    emails_sorted: list[str] = [seen[k] for k in sorted(seen)]

    return {
        "ok": True,
        "content": "\n".join(emails_sorted) if emails_sorted else "",
        "metadata": {
            "count": len(emails_sorted),
            "emails": emails_sorted,
        },
    }


def main() -> None:
    """Legge JSON da stdin, chiama invoke(), scrive JSON su stdout."""
    raw = sys.stdin.read()
    try:
        args = json.loads(raw)
    except json.JSONDecodeError as exc:
        result = {"ok": False, "error": f"JSON non valido in input: {exc}"}
    else:
        result = invoke(args)
    sys.stdout.write(json.dumps(result, ensure_ascii=False))


if __name__ == "__main__":
    main()
